import { Effect } from "effect"
import { join } from "node:path"
import { Files } from "../Files.ts"
import type { Palette } from "../Palette.ts"
import { Paths } from "../Paths.ts"
import { Target } from "../Target.ts"

const name = "discord"
const FILE = "rex.theme.css"

/**
 * A Discord theme for the client mods that load CSS themes. Sets both the
 * classic variables and the 2025 visual-refresh ones.
 */
export const render = (p: Palette): string => `/**
 * @name Rex
 * @author rexeme
 * @version 1.0.0
 * @description Generated by rexeme from Rex's "${p.name}" theme.
 */
:root, .theme-dark, .theme-light, .theme-darker, .theme-midnight {
  --background-primary: ${p.bg};
  --background-secondary: ${p.bgDim};
  --background-secondary-alt: ${p.surface0};
  --background-tertiary: ${p.bgDim};
  --background-floating: ${p.surface0};
  --background-accent: ${p.accent};
  --background-modifier-hover: ${p.surface0};
  --background-modifier-active: ${p.surface1};
  --background-modifier-selected: ${p.surface1};
  --background-base-lowest: ${p.bgDim};
  --background-base-lower: ${p.bgDim};
  --background-base-low: ${p.bg};
  --background-surface-high: ${p.surface0};
  --background-surface-higher: ${p.surface1};
  --background-surface-highest: ${p.surface1};
  --chat-background-default: ${p.bg};
  --channeltextarea-background: ${p.surface0};
  --input-background: ${p.surface0};
  --modal-background: ${p.surface0};
  --text-normal: ${p.fg};
  --text-default: ${p.fg};
  --text-strong: ${p.fg};
  --text-muted: ${p.muted};
  --text-subtle: ${p.subtext};
  --text-link: ${p.blue};
  --header-primary: ${p.fg};
  --header-secondary: ${p.subtext};
  --channels-default: ${p.subtext};
  --interactive-normal: ${p.subtext};
  --interactive-hover: ${p.fg};
  --interactive-active: ${p.fg};
  --interactive-muted: ${p.muted};
  --border-subtle: ${p.border};
  --border-normal: ${p.border};
  --border-strong: ${p.borderStrong};
  --brand-500: ${p.accent};
  --brand-560: ${p.accent};
  --brand-experiment: ${p.accent};
  --status-danger: ${p.error};
  --status-warning: ${p.warning};
  --status-positive: ${p.success};
  --scrollbar-thin-thumb: ${p.borderStrong};
  --scrollbar-auto-thumb: ${p.borderStrong};
  --scrollbar-auto-track: ${p.bgDim};
}
`

/** Client mods by their Application Support folder, and whether rexeme can enable the theme itself. */
const MODS: ReadonlyArray<{ readonly dir: string; readonly settings: "vencord" | "manual" }> = [
  { dir: "Vencord", settings: "vencord" },
  { dir: "Equicord", settings: "vencord" },
  { dir: "BetterDiscord", settings: "manual" },
]

const installed = Effect.gen(function* () {
  const paths = yield* Paths.Service
  return yield* Effect.filter(MODS, (mod) => Target.exists(join(paths.appSupport, mod.dir)))
})

export const target: Target.Target = {
  name,
  detect: Effect.map(installed, (mods) => mods.length > 0),
  apply: Effect.fn("Discord.apply")(function* (palette) {
    const paths = yield* Paths.Service
    const notes: Array<string> = []
    for (const mod of yield* installed) {
      const base = join(paths.appSupport, mod.dir)
      const theme = join(base, "themes", FILE)
      yield* Files.writeIfChanged(theme, render(palette)).pipe(Target.step(name, "write", theme))
      if (mod.settings === "vencord") {
        yield* Target.updateJson(name, join(base, "settings", "settings.json"), (settings) => {
          const enabled = Array.isArray(settings["enabledThemes"]) ? settings["enabledThemes"] : []
          return { ...settings, enabledThemes: enabled.includes(FILE) ? enabled : [...enabled, FILE] }
        })
        notes.push(`${mod.dir} reloads it live`)
      } else {
        notes.push(`enable "Rex" once in ${mod.dir}'s Themes settings`)
      }
    }
    return notes.join("; ")
  }),
}

export * as Discord from "./Discord.ts"
